import{z as s,x as B,o as n,c as A,q as l,j as o,D as t,d as r,s as i,S as p,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"存在性与不动点","description":"","frontmatter":{"title":"存在性与不动点","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ge-existence.md","filePath":"econ/ge-existence.md","lastUpdated":1791413859000}'),d={name:"econ/ge-existence.md"};function D(m,e,u,c,h,b){const E=B("Mermaid");return n(),A("div",null,[e[2]||(e[2]=l('<h1 id="存在性与不动点" tabindex="-1">存在性与不动点 <a class="header-anchor" href="#存在性与不动点" aria-label="Permalink to &quot;存在性与不动点&quot;">​</a></h1><div class="epigraph"><p>我们证明：在凸性与连续性的标准假设下，竞争经济存在均衡价格。</p><footer>—— Arrow and Debreu, Existence of an Equilibrium for a Competitive Economy, Econometrica, 1954</footer></div><p><a href="/econ/production-economy-ge">上一课</a>（带生产的一般均衡）。在此之上，均衡与帕累托集接好了，但句子都以「若均衡存在」为前提。超额需求 \\(z(p)=0\\) 是 \\(L-1\\) 个方程，连续函数不必有零点——除非定义域紧、映射指向自己。缺口是存在性：给哪些假设，拍卖人一定能找到 \\(p^*\\)。本课用不动点，不重写需求理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把价格规范到单纯形 \\(\\Delta=\\{p\\in\\mathbb{R}^L_+:\\sum_\\ell p_\\ell=1\\}\\)。瓦尔拉斯定律说 \\(p\\cdot z(p)=0\\)，齐次性说只相对价格有意义。要找 \\(p^*\\in\\Delta\\) 使 \\(z(p^*)\\le 0\\)。若 \\(z\\) 连续，一个候选是布劳威尔：构造从 \\(\\Delta\\) 到自身的连续映射，其不动点对应出清。<span class="marginnote">不动点的直觉：把一张地图摊平在桌上，另拿一张同款地图揉皱后随手丢在第一张的范围内——总有一点恰好压在它代表的真实位置上。价格映射也一样：把每个价格挪向短缺方向，总有一个价格挪到自己脚下，那就是 \\(p^*\\)。</span></p><p>难处在 \\(z\\) 往往不是函数。偏好凸但不严格凸时，需求是对应；价格为零时需求可能无界。需要把「函数的零点」升级成「上半连续、凸值对应的不动点」——角谷静夫（Kakutani）不动点。Arrow–Debreu 的路线是：先把消费集切成紧集（避免无穷需求），再对「价格 → 最优计划对应」用角谷。</p><h3 id="不要把存在当成唯一或可计算" tabindex="-1">不要把存在当成唯一或可计算 <a class="header-anchor" href="#不要把存在当成唯一或可计算" aria-label="Permalink to &quot;不要把存在当成唯一或可计算&quot;">​</a></h3><p>存在定理不给算法，也不给唯一。多个均衡时，比较静态可以跳到另一个盆地。也不要把不动点证明读成「市场会收敛」：证明是一次性映射的不动点，不是试错动态的稳定性。动态是另一套假设。</p><p><span class="marginnote">布劳威尔：连续 \\(f:\\Delta\\to\\Delta\\) 有不动点。角谷： \\(\\Delta\\) 紧凸，\\(F:\\Delta\\rightrightarrows\\Delta\\) 上半连续、非空紧凸值，则存在 \\(p\\in F(p)\\)。超额需求对应的标准技巧是 \\(F(p)=\\arg\\max_{q\\in\\Delta} q\\cdot z(p)\\)，不动点满足瓦尔拉斯出清。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>交换经济的一套充分条件：消费集闭凸下有界；偏好连续、凸、局部非饱和；禀赋在消费集内部（保证即使某价格为零，也买得起附近的点）。则存在瓦尔拉斯均衡。生产端加：生产集闭凸、包含 \\(0\\)、不能免费生产、不可逆；厂商利润最大的供给对应与消费者需求对应一齐进入广义超额需求。</p><p>证明骨架。把可能用到的消费切到一个足够大的立方体，使最优解不会顶到人为边界。需求对应在 \\(\\Delta\\) 上非空、紧凸值、上半连续。构造</p> \\[F(p)=\\bigl\\{q\\in\\Delta: q\\cdot z(p)\\ge q&#39;\\cdot z(p)\\ \\forall q&#39;\\in\\Delta\\bigr\\}. \\]<p>\\(F\\) 满足角谷条件。不动点 \\(p^*\\in F(p^*)\\) 加上瓦尔拉斯定律推出 \\(z(p^*)\\le 0\\)，正价格市场出清。</p>',14)),(n(),o(p,null,{default:t(()=>[i(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASSUME%5B%22%E8%BF%9E%E7%BB%AD%20%C2%B7%20%E5%87%B8%20%C2%B7%20%E5%86%85%E9%83%A8%E7%A6%80%E8%B5%8B%22%5D%20--%3E%20Z%5B%22%E8%B6%85%E9%A2%9D%E9%9C%80%E6%B1%82%E5%AF%B9%E5%BA%94%20z(p)%22%5D%0A%20%20Z%20--%3E%20K%5B%22%E8%A7%92%E8%B0%B7%EF%BC%9AF(p)%20%E7%9A%84%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A%20%20K%20--%3E%20PSTAR%5B%22%E5%AD%98%E5%9C%A8%20p*%20%E4%BD%BF%E5%B8%82%E5%9C%BA%E5%87%BA%E6%B8%85%22%5D%0A%20%20PSTAR%20--%3E%20NOT%5B%22%E4%B8%8D%E8%95%B4%E5%90%AB%E5%94%AF%E4%B8%80%E3%80%81%E7%A8%B3%E5%AE%9A%E3%80%81%E5%8F%AF%E7%AE%97%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"McKenzie、Gale 等人有平行证明。Debreu《价值理论》把商品空间做成有限维欧氏空间，或有商品的日期–状态指标；本课只钉有限 \\(L\\)。无限维要另用分离与properness，不在主干。",-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"凸性保证需求对应凸值：两点都最优，平均也最优，角谷才吃得下。连续性（偏好的闭图）保证对应上半连续：价格微动，需求不会跳到远处而不把中间点带上。内部禀赋挡住「某商品价格为零时，持有量为零的人需求爆炸」这种边界病。",-1)),e[6]||(e[6]=a("p",null,[r("计价物单纯形是紧凸的，这才有不动点定理的定义域。若允许 \\(p=0\\)，人人把所有商品当免费，需求无界，对应甚至没有值。故存在性证明必须先选正规化。"),a("span",{class:"marginnote"},"「计价物单纯形」翻译成大白话：只有相对价格有意义，就把所有价格除以总值，让它们加起来等于一——相当于所有价格都改用「占一篮子总值几成」来报。这一步把无穷大的价格空间压成一个紧致的小盒子，不动点定理才有舞台。")],-1)),e[7]||(e[7]=a("p",null,[r("存在性与"),a("a",{href:"/econ/welfare-theorems"},"福利定理"),r("的假设几乎同一套，但逻辑方向相反：福利定理假定均衡已在，推有效；存在性假定偏好与技术，推均衡非空。两者合在一起，才谈得上「竞争是一个解」。")],-1)),(n(),o(p,null,{default:t(()=>[i(E,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%7B%22%E5%81%8F%E5%A5%BD%E5%87%B8%3F%22%7D%20--%3E%7C%E5%90%A6%7C%20F1%5B%22%E9%9C%80%E6%B1%82%E9%9D%9E%E5%87%B8%E5%80%BC%3A%20%E8%A7%92%E8%B0%B7%E5%A4%B1%E6%95%88%22%5D%0A%20%20C2%7B%22%E5%81%8F%E5%A5%BD%E8%BF%9E%E7%BB%AD%3F%22%7D%20--%3E%7C%E5%90%A6%7C%20F2%5B%22%E9%9C%80%E6%B1%82%E8%B7%B3%E5%8F%98%3A%20%E9%9D%9E%E4%B8%8A%E5%8D%8A%E8%BF%9E%E7%BB%AD%22%5D%0A%20%20C3%7B%22%E7%A6%80%E8%B5%8B%E5%9C%A8%E5%86%85%E9%83%A8%3F%22%7D%20--%3E%7C%E5%90%A6%7C%20F3%5B%22%E9%9B%B6%E4%BB%B7%E6%97%B6%E9%9C%80%E6%B1%82%E7%88%86%E7%82%B8%3A%20%E8%BE%B9%E7%95%8C%E7%97%85%22%5D%0A%20%20F1%20--%3E%20NO%5B%22%E5%9D%87%E8%A1%A1%E5%8F%AF%E8%83%BD%E4%B8%8D%E5%AD%98%E5%9C%A8%22%5D%0A%20%20F2%20--%3E%20NO%0A%20%20F3%20--%3E%20NO%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=l('<p><span class="marginnote">这张图读法：每条标准假设各挡住一种病。把三条假设想成三道堤坝——凸性管「平均仍最优」，连续性管「价格微动需求不瞬移」，内部禀赋管「免费商品不引来无穷需求」——任何一道溃堤，不动点定理就失去了着力点。</span></p><h3 id="超额需求要满足的三条" tabindex="-1">超额需求要满足的三条 <a class="header-anchor" href="#超额需求要满足的三条" aria-label="Permalink to &quot;超额需求要满足的三条&quot;">​</a></h3><p>标准证明其实在用超额需求的三条性质，而不直接盯着每个人的效用。齐次性：\\(z(\\lambda p)=z(p)\\)。瓦尔拉斯定律：\\(p\\cdot z(p)=0\\)。连续性或对应的上半连续。再加上有界（切立方体之后）和边界行为：某商品价格趋于零时，其超额需求不会掉到负无穷——内部禀赋帮的就是这个忙。满足这几条的 \\(z\\)，不必问它从哪套偏好来，都有零点。Sonnenschein–Mantel–Debreu 后话是：这几条几乎也是 \\(z\\) 的全部限制，所以总体需求可以很任意，唯一性没有免费午餐。</p><p><span class="marginnote">切立方体是权宜：先在大盒子里找均衡，再证明最优解不会顶到盒子壁，否则扩大盒子。无限维商品（Arrow–Debreu 的日期–状态）不能这么切，要用 properness 一类条件，主干不走。</span></p><p>试错动态收敛是更强的性质，需要总替代等，本课不假设。宏观代表性主体把 \\(I=1\\)，存在性退化成一个人的需求在资源约束上有解，凸连续仍然在，只是角谷用不上那么重。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>规模报酬递增、不可分商品、非凸偏好，都会让对应失去凸值，角谷用不上；均衡可能不存在。外部性使「商品」列表不完整，存在的是错误商品空间上的均衡。不对称信息把状态依存商品变成不可观察的合约，Arrow–Debreu 商品不再能列全。</p><p>不动点证明不是计算程序。斯卡夫算法、近似均衡是计算一般均衡的后话。<span class="marginnote">存在 ≠ 唯一：Sonnenschein–Mantel–Debreu 的结果说超额需求几乎不受限制，多均衡是常态而非例外。好比碗底有两个坑，玻璃珠停在哪个坑取决于起点与历史；做比较静态时价格可能「跳盆」，这不是模型算错，是均衡本来就不是一个点。</span>宏观里「代表性主体加市场出清」常常直接假定存在，用的仍是本课这套凸连续，只是人变成了一个。</p><p>后课默认：谈到竞争经济时，在标准凸连续假设下均衡集非空。核与复制经济要在这个非空集上谈收敛。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>福利定理需要均衡；存在性用超额需求在价格单纯形上的不动点。</li><li>函数用布劳威尔，对应用角谷；凸与连续是对应性质的来源。</li><li>存在不是唯一，不是稳定，不是算法。</li><li>非凸、缺市场、不对称信息会拆掉这套假设。</li><li>出处：Arrow and Debreu, <em>Econometrica</em> 1954；Debreu, <em>Theory of Value</em>。</li></ul>',11))])}const C=s(d,[["render",D]]);export{F as __pageData,C as default};
